use std::{fs,path::Path};use serde_json::{json,Value};use sha2::{Digest,Sha256};fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/early-x175");let d=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-29-early-x175");let p=d.join("README.md");let mut s=fs::read_to_string(&p).unwrap();let before="All initial sources, controller bytes, failure records and repairs remain archived.";let after="Initial sources, failure records and repairs are archived; the original setup-controller executable remains local with its recorded SHA256.";assert_eq!(s.matches(before).count(),1);s=s.replace(before,after).replace("ranks4–12 of15, nominal96.484375%","ranks 4–12 of 15, nominal 96.484375%").replace("CPU2 and on CPUs0–31","CPU 2 and on CPUs 0–31");fs::write(&p,s).unwrap();let mut bins=serde_json::Map::new();for f in["native-helper.initial","frozen-probe","off-probe","on-probe"]{let p=r.join(f);bins.insert(p.display().to_string(),json!(hash(&p)));}fs::write(d.join("artifacts/local-binary-sha256.json"),serde_json::to_vec_pretty(&Value::Object(bins)).unwrap()).unwrap();fs::copy(r.join("publication.rs"),d.join("artifacts/publication.rs")).unwrap();fs::write(d.join("artifacts/publication-review.json"),serde_json::to_vec_pretty(&json!({"changes":"clarify local-only original controller executable and prose spacing","numbers_gates_scope_unchanged":true,"before":before,"after":after})).unwrap()).unwrap();}
